package wordsearch

import "errors"

// directions covers all eight ways a word can be hidden:
// horizontal, vertical, and diagonal, in both orientations.
var directions = [8][2]int{
	{1, 0}, {-1, 0}, // left-to-right, right-to-left
	{0, 1}, {0, -1}, // top-to-bottom, bottom-to-top
	{1, 1}, {-1, -1}, // top-left to bottom-right, bottom-right to top-left
	{1, -1}, {-1, 1}, // top-right to bottom-left, bottom-left to top-right
}

// notFound is the placeholder coordinate for a word that is not in the puzzle.
var notFound = [2][2]int{{-1, -1}, {-1, -1}}

// Solve finds each word in the puzzle and returns the coordinates of the
// first and last letter of every word as [x, y] pairs, keyed by word.
// It returns an error if any word cannot be located.
func Solve(words []string, puzzle []string) (map[string][2][2]int, error) {
	result := make(map[string][2][2]int, len(words))

	for _, word := range words {
		if pos, ok := find(word, puzzle); ok {
			result[word] = pos
		} else {
			result[word] = notFound
		}
	}

	for _, word := range words {
		if result[word] == notFound {
			return result, errors.New("could not find all words in the puzzle")
		}
	}

	return result, nil
}

// find searches for word in the puzzle, trying every starting cell and every
// direction. It returns the coordinates of the first and last letter.
func find(word string, puzzle []string) ([2][2]int, bool) {
	rows := len(puzzle)
	if rows == 0 || len(puzzle[0]) == 0 || word == "" {
		return [2][2]int{}, false
	}
	cols := len(puzzle[0])

	for y := 0; y < rows; y++ {
		for x := 0; x < cols; x++ {
			for _, d := range directions {
				if match(word, puzzle, x, y, d[0], d[1]) {
					return [2][2]int{
						{x, y},
						{x + d[0]*(len(word)-1), y + d[1]*(len(word)-1)},
					}, true
				}
			}
		}
	}
	return [2][2]int{}, false
}

// match reports whether word is spelled starting at (x, y) and stepping by
// (dx, dy) each letter, staying inside the puzzle.
func match(word string, puzzle []string, x, y, dx, dy int) bool {
	rows := len(puzzle)
	cols := len(puzzle[0])
	for i := 0; i < len(word); i++ {
		cx, cy := x+dx*i, y+dy*i
		if cx < 0 || cx >= cols || cy < 0 || cy >= rows {
			return false
		}
		if puzzle[cy][cx] != word[i] {
			return false
		}
	}
	return true
}
